import{_ as a,o,c as r,ai as d}from"./chunks/framework.DAbPic9L.js";const b=JSON.parse('{"title":"浏览器 Browser","description":"","frontmatter":{},"headers":[],"relativePath":"disciplines/frontend/basic/browser.md","filePath":"disciplines/frontend/basic/browser.md","lastUpdated":1787215730000}'),l={name:"disciplines/frontend/basic/browser.md"};function i(c,e,t,h,n,p){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="浏览器-browser" tabindex="-1">浏览器 Browser <a class="header-anchor" href="#浏览器-browser" aria-label="Permalink to &quot;浏览器 Browser&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h2><h3 id="进程" tabindex="-1">进程 <a class="header-anchor" href="#进程" aria-label="Permalink to &quot;进程&quot;">​</a></h3><p>应用程序执行时管理自身运行的内存空间。</p><p>进程之间相互独立，进程通信需遵循协议约定。</p><br><h3 id="线程" tabindex="-1">线程 <a class="header-anchor" href="#线程" aria-label="Permalink to &quot;线程&quot;">​</a></h3><p>扮演执行程序代码的系统角色，且进程至少存在一个线程（主线程），保证进程不浪费空间。</p><p>若主线程忙不过来，可开辟多线程处理（特定任务），提高程序的并发性。</p><br><h3 id="同步" tabindex="-1">同步 <a class="header-anchor" href="#同步" aria-label="Permalink to &quot;同步&quot;">​</a></h3><p>程序代码逐行执行，当前执行未结束，后续执行需等待。</p><br><h3 id="异步" tabindex="-1">异步 <a class="header-anchor" href="#异步" aria-label="Permalink to &quot;异步&quot;">​</a></h3><p>程序代码逐行执行，当前执行交给事件循环，由事件循环决定时机返回事件回调；无需等待当前执行结果，继续后续执行。</p><h2 id="浏览器进程模型" tabindex="-1">浏览器进程模型 <a class="header-anchor" href="#浏览器进程模型" aria-label="Permalink to &quot;浏览器进程模型&quot;">​</a></h2><p>浏览器进程模型主要包括浏览器进程、网络进程、渲染进程、以及其它进程。</p><br><h3 id="浏览器进程" tabindex="-1">浏览器进程 <a class="header-anchor" href="#浏览器进程" aria-label="Permalink to &quot;浏览器进程&quot;">​</a></h3><p>负责浏览器界面显示、用户交互、子进程管理等内容。</p><p>比如标题、书签、地址栏，<code>Cookie</code>、前进后退刷新等内容管理。</p><br><h3 id="网络进程" tabindex="-1">网络进程 <a class="header-anchor" href="#网络进程" aria-label="Permalink to &quot;网络进程&quot;">​</a></h3><p>负责网络资源管理（加载、下载），内部会通过多线程处理不同网络任务。</p><p>比如资源下载，加载、预解析网络资源。</p><br><h3 id="渲染进程" tabindex="-1">渲染进程 <a class="header-anchor" href="#渲染进程" aria-label="Permalink to &quot;渲染进程&quot;">​</a></h3><p>自动开启渲染主线程，负责解析、执行<code>HTML</code>、<code>CSS</code>、<code>JavaScript</code>代码，并渲染展示页面内容。</p><p>现代浏览器采用多进程多线程的进程模型；每一个标签页就是一个进程，互不干扰。</p><h2 id="事件循环机制" tabindex="-1">事件循环机制 <a class="header-anchor" href="#事件循环机制" aria-label="Permalink to &quot;事件循环机制&quot;">​</a></h2><p>渲染主线程的工作流程包括但不限于解析<code>HTML</code>文档、层叠样式计算、几何布局构建、图层分层堆叠、绘制指令生成、分块切割内容，内容光栅位图，位图指引编排，像素界面显示、全局执行<code>JS</code>代码、处理用户交互事件、定时器回调等任务内容。</p><br><h3 id="事件循环模型" tabindex="-1">事件循环模型 <a class="header-anchor" href="#事件循环模型" aria-label="Permalink to &quot;事件循环模型&quot;">​</a></h3><p>由于渲染主线程需要处理以上内容，并非触发则立即执行；因此引入事件循环（<code>消息队列</code>），解决任务调度有序问题。本质上通过消息队列、循环检出任务执行来解决问题。</p><br><p><strong>工作原理</strong></p><ol><li><p>打开标签页（<code>渲染进程</code>），渲染主线程（<code>自启动</code>）进入无限循环。</p></li><li><p>在每次循环中检出任务，存在则从消息队列里取出并执行；否则进入休眠状态，等待下一次检出激活执行。</p></li><li><p>执行取出任务时，可能产生新任务，新任务就添加到消息队列里；如此往复，直到本次循环结束。</p></li><li><p>其它线程也有可能产生新任务，也会添加到消息队列里。如用户交互事件处理，会打包成任务添加到消息队列里。</p></li><li><p>事件循环（<code>消息队列</code>）的引入，让渲染主线程的任务执行变得有条不紊，高效执行。</p></li></ol><br><h3 id="异步编程模型" tabindex="-1">异步编程模型 <a class="header-anchor" href="#异步编程模型" aria-label="Permalink to &quot;异步编程模型&quot;">​</a></h3><p>虽然事件循环解决了任务有序调度问题，但由于渲染主线程存在某些任务无法及时处理（<code>执行过程太耗时</code>），渲染主线程会造成阻塞，浪费等待过程的渲染时间。而渲染主线程无论如何都不能造成阻塞，否则就会引起页面卡顿、白屏等问题；因此引入异步编程模型，解决任务调度优先级问题。</p><br><p><strong>W3C 规范说明</strong></p><ul><li>渲染主线程的任务没有优先级，遵循消息队列“先进先出”的执行顺序。</li><li>消息队列有优先级。<code>W3C</code>规范规定，每个任务都有一个任务类型，不同任务类型的任务存放在不同的消息队列里；另外，规定浏览器存在一个微队列，且微队列的任务优先于所有其它任务执行。</li><li>强化理解（谷歌浏览器队列优先级）: 微队列 &gt; 交互队列 &gt; 延时队列 &gt; 其它队列。</li><li>特别提醒: 老版本浏览器的概念（微任务、宏任务）已不再适应现代浏览器的实现流程，而是将宏任务拆分成不同种类的任务队列，以适应现代浏览器的调度需要。</li></ul><br><p><strong>工作原理</strong></p><ol><li><p>渲染主线程执行全局<code>JS</code>程序代码，在遵循事件循环模型基础上，遇到无法及时处理（<code>执行过程太耗时</code>）的任务，将提交给其它线程处理，结束当前任务，继续执行后续任务。</p></li><li><p>当其它线程任务处理完毕，通过事件回调方式把处理结果打包成任务并加入到渲染主线程的消息队列里，等待调度执行。</p></li></ol><br><h3 id="个人归档总结" tabindex="-1">个人归档总结 <a class="header-anchor" href="#个人归档总结" aria-label="Permalink to &quot;个人归档总结&quot;">​</a></h3><ol><li><p><code>JS</code>是一门单线程的编程语言，浏览器渲染主线程要负责解析<code>HTML</code>文档、层叠样式计算、几何布局构建、图层分层堆叠、绘制指令生成、分块切割内容，内容光栅位图，位图指引编排，像素界面显示、全局执行<code>JS</code>代码、处理用户交互事件、定时器回调等任务内容。</p></li><li><p>通过事件循环模型，渲染主线程开启无限循环模式，利用消息队列将任务逐个取出，保证渲染主线程任务调度有序执行。但渲染主线程可能存在无法立即处理的任务，导致浏览器渲染阻塞产生白屏、卡死等问题，造成不好的用户体验。</p></li><li><p>通过异步编程模型，渲染主线程将无法立即处理的任务交给其它线程处理，并结束当前任务，继续执行下一个任务。当其它线程完成后，会将事件回调打包成任务并加入到渲染主线程的消息队列里，等待调度执行。另外，<code>W3C</code>官方规范说明，每个任务有不同的任务类型，根据任务类型存储在不同的消息队列里；且规定浏览器必须存在个微队列，微队列任务优先于其它所有队列任务执行。也就是说，消息队列有优先级；如此，渲染主线程永不阻塞，最大限度保证单线程的流畅运行。</p></li></ol><h2 id="渲染主线程流程内容" tabindex="-1">渲染主线程流程内容 <a class="header-anchor" href="#渲染主线程流程内容" aria-label="Permalink to &quot;渲染主线程流程内容&quot;">​</a></h2><p>浏览器网络主线程接收到<code>HTML</code>文档后，产生渲染任务并添加到渲染主线程的消息队列里，等待调度执行。在事件循环机制下，渲染主线程取出渲染任务，开启渲染流程。</p><br><h3 id="文档内容解析" tabindex="-1">文档内容解析 <a class="header-anchor" href="#文档内容解析" aria-label="Permalink to &quot;文档内容解析&quot;">​</a></h3><ol><li><p>解析<code>HTML</code>文档前，浏览器快速扫描抓取外部资源链接（<code>link</code>、<code>script</code>、<code>img</code>等），并率先下载相关网络资源到本地缓存。</p></li><li><p>解析过程遵循“遇到<code>CSS</code>解析<code>CSS</code>,遇到<code>JS</code>解析并执行<code>JS</code>”的代码原则。</p></li><li><p>当解析到<code>link</code>标签时，渲染主线程不会等待，而是开启预解析线程来解析<code>CSS</code>；这也是渲染主线程不会阻塞<code>CSS</code>的根本原因。</p></li><li><p>当解析到<code>script</code>标签时，渲染主线程会暂停，等待<code>JS</code>执行完毕，才继续后续解析；因为<code>JS</code>可能会修改<code>DOM</code>结构，这也是渲染主线程会阻塞<code>JS</code>的根本原因。</p></li><li><p>解析<code>HTML</code>文档完毕，渲染主线程最终将<code>HTML</code>文档内容解析成<code>DOM</code>树，并将<code>CSS</code>样式表解析成<code>CSSOM</code>树。分别可在浏览器通过<code>document.documentElement</code>、<code>document.styleSheets</code>等属性获取。</p></li></ol><br><h3 id="层叠样式计算" tabindex="-1">层叠样式计算 <a class="header-anchor" href="#层叠样式计算" aria-label="Permalink to &quot;层叠样式计算&quot;">​</a></h3><p>渲染主线程遍历<code>DOM</code>树，依次为树中的每个节点计算出最终样式。</p><ol><li><p>确定明确值: 将预设值、默认值、用户自定义值等转换为明确值。</p></li><li><p>样式值层叠: 根据样式表来源、选择器权重、书写源次序等确定部分最终样式。</p></li><li><p>样式值继承: 样式属性值未设置，且属性规则有继承能力，会继承上层元素的样式。</p></li><li><p>样式值默认: 样式属性值未设置，且属性规则无继承能力，会沿用浏览器默认样式。</p></li></ol><br><p><code>CSS</code>属性值的计算过程，会优先确定明确值（转换为绝对长度或其他单位），并通过有值不冲突确认部分最终样式，有值冲突则根据样式层叠规则确定最终样式。对于无值样式属性，有继承能力则继承上层元素的样式，无继承能力则沿用浏览器默认样式。</p><br><h3 id="几何布局构建" tabindex="-1">几何布局构建 <a class="header-anchor" href="#几何布局构建" aria-label="Permalink to &quot;几何布局构建&quot;">​</a></h3><p>渲染主线程遍历<code>DOM</code>节点，计算出每个节点的几何信息（节点宽高、包含快的相对位置等）。</p><br><h4 id="树型结构不一" tabindex="-1">树型结构不一 <a class="header-anchor" href="#树型结构不一" aria-label="Permalink to &quot;树型结构不一&quot;">​</a></h4><ul><li>设置<code>display:none</code>的节点不产生几何信息，因此在<code>Layout</code>树结构不可见。</li><li>设置样式伪类元素，在<code>DOM</code>树结构中不可见，但在<code>Layout</code>树结构中可见。</li></ul><br><h4 id="布局树规则" tabindex="-1">布局树规则 <a class="header-anchor" href="#布局树规则" aria-label="Permalink to &quot;布局树规则&quot;">​</a></h4><ul><li>块盒和行盒不能相邻，且内容必须在行盒内。</li><li>浏览器会通过匿名行盒或匿名块盒自动补全布局编排。</li></ul><br><h4 id="回流渲染" tabindex="-1">回流渲染 <a class="header-anchor" href="#回流渲染" aria-label="Permalink to &quot;回流渲染&quot;">​</a></h4><p>当元素的几何信息发生变化时（位置、大小、结构），浏览器必须重新计算布局。</p><br><h3 id="图层分层堆叠" tabindex="-1">图层分层堆叠 <a class="header-anchor" href="#图层分层堆叠" aria-label="Permalink to &quot;图层分层堆叠&quot;">​</a></h3><p>渲染主线程使用一套复杂策略对整个布局进行图层分层，使得在未来某一图层发生变化，仅重新处理该图层，而不影响其它图层，从而提高渲染效率。其主要目的是减少重绘氛围，并利用<code>GPU</code>加速。</p><br><h4 id="图层分层因素" tabindex="-1">图层分层因素 <a class="header-anchor" href="#图层分层因素" aria-label="Permalink to &quot;图层分层因素&quot;">​</a></h4><ul><li>元素透明度(<code>opacity</code>)。</li><li>堆叠上下文(<code>z-index</code>)。</li><li>元素变换(<code>transform</code>)。</li><li>细粒控制（<code>will-change</code>）。</li><li>滚动条(<code>scroll</code>连续触发)。</li><li>元素动画(<code>animation</code>持续特效)。</li></ul><br><h3 id="绘制指令生成" tabindex="-1">绘制指令生成 <a class="header-anchor" href="#绘制指令生成" aria-label="Permalink to &quot;绘制指令生成&quot;">​</a></h3><p>渲染主线程为每个图层单独产生绘制指令集，用于描述这一层如何画出来。</p><p>当完成绘制后，渲染主线程将每个图层的绘制信息提交给合成线程。</p><br><h4 id="流程界限" tabindex="-1">流程界限 <a class="header-anchor" href="#流程界限" aria-label="Permalink to &quot;流程界限&quot;">​</a></h4><p class="text-red">由渲染主线程转交给合成线程继续处理后续工作。</p><br><h4 id="重绘渲染" tabindex="-1">重绘渲染 <a class="header-anchor" href="#重绘渲染" aria-label="Permalink to &quot;重绘渲染&quot;">​</a></h4><p>当元素的外观发生变化（颜色、背景、边框色、盒阴影、占位可见等），但不影响布局时，只需要重新绘制。</p><br><h3 id="分块切割内容" tabindex="-1">分块切割内容 <a class="header-anchor" href="#分块切割内容" aria-label="Permalink to &quot;分块切割内容&quot;">​</a></h3><p>合成线程通过多线程并发对每个图层进行分块，划分为更多小区域内容块。</p><br><h3 id="内容光栅位图" tabindex="-1">内容光栅位图 <a class="header-anchor" href="#内容光栅位图" aria-label="Permalink to &quot;内容光栅位图&quot;">​</a></h3><p>合成线程将分块内容提交给<code>CPU</code>进程，优先处理屏幕显示区分块内容，以极高速度完成光栅化，最终产生位图。</p><br><h4 id="元素变形" tabindex="-1">元素变形 <a class="header-anchor" href="#元素变形" aria-label="Permalink to &quot;元素变形&quot;">​</a></h4><p>当元素发生位移、旋转、缩放等变形时，合成线程会重新生成位图。</p><br><h3 id="位图指引编排" tabindex="-1">位图指引编排 <a class="header-anchor" href="#位图指引编排" aria-label="Permalink to &quot;位图指引编排&quot;">​</a></h3><p>合成线程拿到每个图层的位图，生成一个个指引信息；每个指引信息会标识位图应该画到屏幕的某个位置，以及旋转、缩放等变形操作。</p><br><h3 id="像素界面显示" tabindex="-1">像素界面显示 <a class="header-anchor" href="#像素界面显示" aria-label="Permalink to &quot;像素界面显示&quot;">​</a></h3><p>合成线程将每个指引信息提交给<code>GPU</code>进程，<code>GPU</code>进程将图层的像素信息绘制到屏幕上。</p>',105)])])}const u=a(l,[["render",i]]);export{b as __pageData,u as default};
